selector_to_html = {"a[href=\"#haive-mcp-documentation\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Haive MCP Documentation<a class=\"headerlink\" href=\"#haive-mcp-documentation\" title=\"Link to this heading\">\u00b6</a></h1><h2>Welcome to Haive MCP<a class=\"headerlink\" href=\"#welcome-to-haive-mcp\" title=\"Link to this heading\">\u00b6</a></h2><p>Haive MCP (Model Context Protocol) revolutionizes how AI agents acquire capabilities by enabling <strong>dynamic, runtime integration</strong> of tools, resources, and prompts from a vast ecosystem of <strong>1900+ MCP servers from top GitHub repositories</strong>.</p><p>\ud83d\ude80 <strong>The Game Changer</strong>: Your agents can now <strong>automatically discover and integrate</strong> the exact tools they need, when they need them, without any predefined configuration!</p>", "a[href=\"#key-features\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Key Features<a class=\"headerlink\" href=\"#key-features\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#what-is-mcp\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">What is MCP?<a class=\"headerlink\" href=\"#what-is-mcp\" title=\"Link to this heading\">\u00b6</a></h3><p>Model Context Protocol (MCP) is an open standard that allows AI systems to securely connect to data sources and tools. With MCP, your agents can:</p>", "a[href=\"#massive-server-discovery-database\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Massive Server Discovery Database<a class=\"headerlink\" href=\"#massive-server-discovery-database\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#dynamic-integration-at-its-core\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Dynamic Integration at Its Core<a class=\"headerlink\" href=\"#dynamic-integration-at-its-core\" title=\"Link to this heading\">\u00b6</a></h3><p>Imagine an agent that starts with zero tools but can:</p>", "a[href=\"#quick-example-dynamic-discovery-in-action\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Quick Example: Dynamic Discovery in Action<a class=\"headerlink\" href=\"#quick-example-dynamic-discovery-in-action\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#next-steps\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Next Steps<a class=\"headerlink\" href=\"#next-steps\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"installation.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Installation<a class=\"headerlink\" href=\"#installation\" title=\"Link to this heading\">\u00b6</a></h1><h2>Installing haive-mcp<a class=\"headerlink\" href=\"#installing-haive-mcp\" title=\"Link to this heading\">\u00b6</a></h2><p>The haive-mcp package is part of the Haive framework. You can install it using Poetry:</p>", "a[href=\"#getting-help\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Help<a class=\"headerlink\" href=\"#getting-help\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#welcome-to-haive-mcp\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Welcome to Haive MCP<a class=\"headerlink\" href=\"#welcome-to-haive-mcp\" title=\"Link to this heading\">\u00b6</a></h2><p>Haive MCP (Model Context Protocol) revolutionizes how AI agents acquire capabilities by enabling <strong>dynamic, runtime integration</strong> of tools, resources, and prompts from a vast ecosystem of <strong>1900+ MCP servers from top GitHub repositories</strong>.</p><p>\ud83d\ude80 <strong>The Game Changer</strong>: Your agents can now <strong>automatically discover and integrate</strong> the exact tools they need, when they need them, without any predefined configuration!</p>", "a[href=\"getting_started.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Started<a class=\"headerlink\" href=\"#getting-started\" title=\"Link to this heading\">\u00b6</a></h1><p>Welcome to haive-mcp! Get up and running with 1900+ MCP servers in minutes.</p>", "a[href=\"quickstart.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Quick Start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">\u00b6</a></h1><p>This guide will get you up and running with haive-mcp in 5 minutes.</p>", "a[href=\"examples.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Examples<a class=\"headerlink\" href=\"#examples\" title=\"Link to this heading\">\u00b6</a></h1><p>Comprehensive examples demonstrating haive-mcp capabilities with 1900+ MCP servers.</p>", "a[href=\"#indices-and-tables\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Indices and tables<a class=\"headerlink\" href=\"#indices-and-tables\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#id1\"]": "<div class=\"literal-block-wrapper docutils container\" id=\"id1\">\n<div class=\"code-block-caption\"><span class=\"caption-text\">Watch an agent automatically discover and integrate tools</span><a class=\"headerlink\" href=\"#id1\" title=\"Link to this code\">\u00b6</a></div>\n<div class=\"highlight-python notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">haive.mcp.agents</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">IntelligentMCPAgent</span>\n<span class=\"kn\">from</span><span class=\"w\"> </span><span class=\"nn\">haive.core.engine</span><span class=\"w\"> </span><span class=\"kn\">import</span> <span class=\"n\">AugLLMConfig</span>\n\n<span class=\"c1\"># Create an intelligent agent with dynamic discovery</span>\n<span class=\"n\">agent</span> <span class=\"o\">=</span> <span class=\"n\">IntelligentMCPAgent</span><span class=\"p\">(</span>\n    <span class=\"n\">engine</span><span class=\"o\">=</span><span class=\"n\">AugLLMConfig</span><span class=\"p\">(),</span>\n    <span class=\"n\">auto_discover</span><span class=\"o\">=</span><span class=\"kc\">True</span>  <span class=\"c1\"># Enable automatic tool discovery</span>\n<span class=\"p\">)</span>\n\n<span class=\"c1\"># Ask it to do something - it will find the tools it needs!</span>\n<span class=\"n\">result</span> <span class=\"o\">=</span> <span class=\"k\">await</span> <span class=\"n\">agent</span><span class=\"o\">.</span><span class=\"n\">arun</span><span class=\"p\">({</span>\n    <span class=\"s2\">\"messages\"</span><span class=\"p\">:</span> <span class=\"p\">[{</span>\n        <span class=\"s2\">\"role\"</span><span class=\"p\">:</span> <span class=\"s2\">\"user\"</span><span class=\"p\">,</span>\n        <span class=\"s2\">\"content\"</span><span class=\"p\">:</span> <span class=\"s2\">\"Search GitHub for Python AI projects and create a report\"</span>\n    <span class=\"p\">}]</span>\n<span class=\"p\">})</span>\n</pre></div>\n</div>\n</div>"}
skip_classes = ["headerlink", "sd-stretched-link", "reference-external"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`div.content ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }
            link.classList.add('has-tooltip');
            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: true, theme: 'light-border', delay: [200, 100], duration: [200, 100],
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
